def encode_shift(s: str):
    """
    Returns encoded string by shifting every character by 5 in the alphabet.
    Only lowercase letters a-z are shifted; other characters remain unchanged.
    """
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            result.append(chr(((ord(ch) + 5 - ord("a")) % 26) + ord("a")))
        else:
            result.append(ch)
    return "".join(result)


def decode_shift(s: str):
    """
    Takes as input string encoded with encode_shift function.
    Returns decoded string by shifting every character by -5 in the alphabet.
    Only lowercase letters a-z are shifted; other characters remain unchanged.
    """
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            result.append(chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")))
        else:
            result.append(ch)
    return "".join(result)


# Example usage:
if __name__ == "__main__":
    original = "hello world"
    encoded = encode_shift(original)
    decoded = decode_shift(encoded)
    print(f"Original: {original}")
    print(f"Encoded : {encoded}")
    print(f"Decoded : {decoded}")
