def search(lst):
    # Initialize a dictionary to store the frequency of each number
    freq_dict = {}

    # Calculate the frequency of each number in the list
    for num in lst:
        if num in freq_dict:
            freq_dict[num] += 1
        else:
            freq_dict[num] = 1

    # Initialize the result to -1
    result = -1

    # Iterate through the dictionary to find the greatest number fulfilling the condition
    for value, count in freq_dict.items():
        if value > 0 and count >= value:
            result = value
            break

    return result

