def search(lst):
    # Calculate the frequency of each item in the list
    frequency = {}
    for item in lst:
        if item in frequency:
            frequency[item] += 1
        else:
            frequency[item] = 1

    # Initialize the result to be returned
    result = -1

    # Search for the integer that meets the conditions
    for item, freq in frequency.items():
        if item > 0 and freq >= item:
            result = max(result, item)

    return result

