def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5)+1):
        if n % i == 0:
            return False
    return True

def is_multiply_prime(a):
    """
    Returns True if a can be expressed as the product of exactly 3 prime numbers,
    and False otherwise.
    """
    if a < 2:
        return False
    # Since a < 100, we can simply try all combinations of 3 primes whose product equals a
    primes = [p for p in range(2, 100) if is_prime(p)]

    for i in range(len(primes)):
        for j in range(i, len(primes)):
            for k in range(j, len(primes)):
                if primes[i] * primes[j] * primes[k] == a:
                    return True
    return False

