def is_multiply_prime(a):
    """Return True if a is the multiplication of exactly 3 prime numbers, False otherwise.
    a < 100
    Example:
    is_multiply_prime(30) == True because 30 = 2 * 3 * 5
    """

    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    # Since a < 100, primes involved must be <= a.
    # We want to check if a can be expressed as p * q * r where p, q, r are primes.
    # Order doesn't matter, but we must confirm exactly three primes multiply to a.

    primes = [p for p in range(2, a + 1) if is_prime(p)]

    for i in range(len(primes)):
        for j in range(i, len(primes)):
            for k in range(j, len(primes)):
                if primes[i] * primes[j] * primes[k] == a:
                    return True
    return False


# Example tests
if __name__ == "__main__":
    print(is_multiply_prime(30))  # True (2*3*5)
    print(is_multiply_prime(60))  # True (2*2*15 no, 2*3*10 no, 2*5*6 no, 3*5*4 no, but 2*2*15 not primes, 2*2*3*5 too many)
    print(is_multiply_prime(105)) # False (greater than 100)
    print(is_multiply_prime(64))  # False (2*2*16 no)
    print(is_multiply_prime(8))   # True (2*2*2)
