def choose_num(x, y):
    # Check if either x or y is not positive
    if x <= 0 or y <= 0:
        raise ValueError("Both x and y must be positive numbers")

    # Find the biggest even number in the range [x, y]
    if y < x:
        return -1

    if x % 2 == 0 and x <= y:
        return x
    elif y % 2 == 0 and y >= x:
        return y
    else:
        even_x = x + (2 - x % 2)
        even_y = y - (y % 2)
        return max(even_x, even_y)

