def minPath(grid, k):
    N = len(grid)
    value_to_position = {}
    for i in range(N):
        for j in range(N):
            value_to_position[grid[i][j]] = (i, j)

    def neighbors(x, y):
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                yield nx, ny

    def find_min_path(start_x, start_y):
        visited = set()
        path = []
        current_x, current_y = start_x, start_y

        for _ in range(k):
            path.append(grid[current_x][current_y])
            visited.add((current_x, current_y))

            next_cell = None
            for nx, ny in neighbors(current_x, current_y):
                if (nx, ny) not in visited:
                    if next_cell is None or grid[nx][ny] < grid[next_cell[0]][next_cell[1]]:
                        next_cell = (nx, ny)

            if next_cell is None:
                break

            current_x, current_y = next_cell

        return path

    min_path = None
    min_path_value = float('inf')

    for x in range(N):
        for y in range(N):
            path = find_min_path(x, y)
            path_value = int(''.join(map(str, path)))

            if path_value < min_path_value:
                min_path_value = path_value
                min_path = path

    return min_path

