def minPath(grid, k):
    N = len(grid)
    min_value = float('inf')
    min_path = []

    def dfs(x, y, path):
        nonlocal min_value, min_path
        if len(path) == k:
            value = path[-1]
            if value < min_value:
                min_value = value
                min_path = path[:]
            return

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                if grid[nx][ny] not in path:
                    path.append(grid[nx][ny])
                    dfs(nx, ny, path)
                    path.pop()

    for i in range(N):
        for j in range(N):
            dfs(i, j, [grid[i][j]])

    return min_path

