def tri(n):
    """Return the first n + 1 numbers in the Tribonacci sequence."""
    if n < 0:
        return []

    tri_seq = [3]  # Base case
    for i in range(1, n+1):
        if i == 1:
            tri_seq.append(1 + i // 2)
        elif i % 2 == 0:
            tri_seq.append(1 + i // 2)
        else:
            tri_seq.append(tri_seq[i-1] + tri_seq[i-2] + tri_seq[i])
    return tri_seq[:n+1]

