def tri(n):
    """Return the first n + 1 numbers of the Tribonacci sequence."""
    def tribonacci(n):
        if n == 1:
            return [3]
        elif n == 2:
            return [3, 2]
        sequence = [3, 2]
        for i in range(2, n + 1):
            if i % 2 == 0:
                sequence.append(1 + i / 2)
            else:
                sequence.append(sequence[i - 1] + sequence[i - 2] + sequence[i + 1])
        return sequence

    return tribonacci(n)


