def comb_sort(arr):
    gap = len(arr)
    shrink = 1.3

    # Start with a big gap, then reduce the gap
    while gap > 1:
        gap = int(gap / shrink)
        for i in range(len(arr) - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]  # Swap elements

    # Perform a bubble sort on the reduced gap to complete the sort
    def bubble_sort(sub_arr):
        n = len(sub_arr)
        for i in range(n):
            for j in range(0, n - i - 1):
                if sub_arr[j] > sub_arr[j + 1]:
                    sub_arr[j], sub_arr[j + 1] = sub_arr[j + 1], sub_arr[j]

    # Apply bubble sort on the sorted subarrays
    for i in range(0, len(arr), gap):
        bubble_sort(arr[i:i + gap])

    return arr

