    def get_gap(gap):
        gap /= 1.3
        return max(gap, 1)

    gap = len(lst)
    sorted = False

    while not sorted:
        gap = get_gap(gap)
        sorted = True

        for i in range(len(lst) - gap):
            if lst[i] > lst[i + gap]:
                lst[i], lst[i + gap] = lst[i + gap], lst[i]
                sorted = False
    return lst


