def lps(s: str) -> int:
    s = s.replace(" ", "")  # Remove spaces as the example suggests ignoring them
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    # Subsequences of length 1 are palindromes of length 1
    for i in range(n):
        dp[i][i] = 1

    # Build the dp table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                dp[i][j] = 2 + (dp[i + 1][j - 1] if length > 2 else 0)
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    return dp[0][n - 1]

assert lps("TENS FOR TENS") == 5
