def longest_palindromic_subsequence(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    # Base case: if the string is empty, the length of the longest palindromic subsequence is 0
    for i in range(n):
        dp[i][i] = 1

    # Fill the dp table
    for i in range(1, n):
        for j in range(i):
            if s[i] == s[j]:
                dp[i][j] = 2 + dp[i-1][j-1]
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    # The length of the longest palindromic subsequence is the maximum value in the dp table
    return max(dp)

