def dog_age(years):
    """Calculate a dog's age in dog's years."""
    # The common rule of thumb is that the first year of a dog's life is equivalent to 15 human years,
    # the second year to nine years, and every subsequent year to five years.
    if years <= 1:
        return 15 * years
    elif years <= 3:
        return 9 * (years - 1)
    else:
        return 5 * (years - 2)

