def max_val(lst):
    """
    Returns the maximum value from a given heterogeneous list.
    The comparison is done based on numerical values;
    non-numeric items are treated as 0.
    """
    max_num = float('-inf')
    for item in lst:
        if isinstance(item, (int, float)):
            if item > max_num:
                max_num = item
        elif isinstance(item, str):
            try:
                num = float(item)
                if num > max_num:
                    max_num = num
            except ValueError:
                continue
    return max_num

