        return 0

    n = len(arr)
    dp = [0] * n
    dp[i] = arr[i]
    max_sum = arr[i]

    for j in range(i + 1, n):
        if arr[j] > arr[i]:
            dp[j] = dp[i] + arr[j]
            max_sum = max(max_sum, dp[j])
        else:
            dp[j] = arr[j]

