def count_occurrence(tup, list_to_count):
    """
    Count the occurrence of all elements of a list in a tuple.

    Args:
    tup (tuple): The tuple in which to count occurrences.
    list_to_count (list): The list of elements to count occurrences for.

    Returns:
    dict: A dictionary with elements as keys and their counts in the tuple as values.
    """
    # Initialize an empty dictionary to store the counts
    counts = {element: 0 for element in list_to_count}

    # Count occurrences of each element in the tuple
    for element in tup:
        if element in counts:
            counts[element] += 1

    return counts


