def tuple_intersection(list1, list2):
    """
    Find the intersection of tuples in two lists, considering tuples equal irrespective of order.

    Args:
    list1: List of tuples.
    list2: List of tuples.

    Returns:
    A set of tuples that appear in both lists ignoring order within the tuples.
    """
    # Normalize tuples by sorting their elements
    normalized1 = {tuple(sorted(t)) for t in list1}
    normalized2 = {tuple(sorted(t)) for t in list2}

    # Find intersection of normalized tuples
    intersect = normalized1.intersection(normalized2)

    # Return the intersecting tuples in the original order as they appeared first in list1
    # This is to match the expected output format (without sorted tuples, just original ones)
    # Create a lookup from normalized tuple to original tuple in list1 (first occurrence)
    lookup = {}
    for t in list1:
        key = tuple(sorted(t))
        if key not in lookup:
            lookup[key] = t

    return {lookup[t] for t in intersect}


