def jacobsthal_num(n):
    # Base cases
    if n == 0:
        return 0
    elif n == 1:
        return 1
    elif n == 2:
        return 1

    # Function to find the Jacobsthal number using the recurrence relation
    def jacobsthal_rec(n):
        if n == 3:
            return 3
        else:
            return 2 * jacobsthal_rec(n - 1) + jacobsthal_rec(n - 2)

    # Compute the Jacobsthal number using the recursive function
    return jacobsthal_rec(n)

