def is_polite(n):
    """
    Finds the nth polite number. A polite number is a positive integer, 
    for which there are at least as many composite (non-prime) numbers 
    less than the number itself as prime numbers.

    Args:
    n (int): The nth position to find.

    Returns:
    int: The nth polite number.
    """

    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    count = 0 # To count primes
    i = 1 # Starting number

    while True:
        if not is_prime(i):
            count += 1 # Increment for composite number
        else:
            count = 0 # Reset count for primes

        # Check if the cumulative count of composites >= primes
        if count >= sum(is_prime(j) for j in range(1, i)):
            n -= 1
            if n == 0:
                return i
        i += 1

# Test the function
