def is_polite(n):
    def is_polite_number(num):
        count = 0
        for i in range(1, num):
            if num % i == 0:
                count += 1
        return count == phi(num) - 1

    def phi(n):
        result = n
        p = 2
        while p * p <= n:
            if n % p == 0:
                while n % p == 0:
                    n //= p
                result -= result // p
            p += 1
        if n > 1:
            result -= result // n
        return result

    i = 1
    while n > 0:
        i += 1
        if is_polite_number(i):
            n -= 1
    return i

